INSERT OR IGNORE INTO categories(id,name,slug,description,icon,color,sort_order,description_limit,search_text,created_at,updated_at)
SELECT id,name,slug,description,icon,color,sort_order,description_limit,search_text,strftime('%Y-%m-%dT%H:%M:%fZ','now'),strftime('%Y-%m-%dT%H:%M:%fZ','now')
FROM initial
WHERE NOT EXISTS (SELECT 1 FROM system_state WHERE key='seed-v1');
